mapper.select:
select ifnull(sum(a.trxActAmount), 0) from WalletAssetTransactions a where trxType='withDraw' and trxStatus != 'failed' and concat(date_format(FROM_UNIXTIME(a.createTime / 1000), '%Y-%m-%d'), '') = date_format(curdate(), '%Y-%m-%d')
and accountId = #{accountId}
and trxAccountNo = #{accountNo}
